import type { JSX } from "@solidjs/web";
export type Style = JSX.CSSProperties | string;
type Own = "id" | "children" | "style" | "aria-label" | "aria-labelledby" | "aria-describedby";
type Of<Tag extends keyof JSX.IntrinsicElements, Less extends string = never> = Omit<JSX.IntrinsicElements[Tag], Own | Less> & { id?: string; style?: Style; "aria-label"?: string; "aria-labelledby"?: string; "aria-describedby"?: string; [data: `data-${string}`]: unknown };
export type Div = Of<"div", "onChange"> & { children?: JSX.Element };
export type Span = Of<"span"> & { children?: JSX.Element };
export type Label = Of<"label"> & { children?: JSX.Element };
export type H3 = Of<"h3"> & { children?: JSX.Element };
export type Input = Of<"input">;
export type Button = Of<"button"> & { children?: JSX.Element };
export type Validation = "valid" | "invalid";
export type Hr = Of<"hr">;
export type Nav = Of<"nav"> & { children?: JSX.Element };
export type Anchor = Of<"a"> & { children?: JSX.Element };
export type P = Of<"p"> & { children?: JSX.Element };
export type H2 = Of<"h2"> & { children?: JSX.Element };
export type Ul = Of<"ul", "onChange"> & { children?: JSX.Element };
export type Li = Of<"li", "value"> & { children?: JSX.Element };
export type Ol = Of<"ol"> & { children?: JSX.Element };
